def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # The upper patterned band is the first contiguous run of rows containing
    # the non-background color.
    rows = [r for r in range(h) if any(x != bg for x in grid[r])]
    if not rows:
        return out
    start = rows[0]
    end = start
    while end + 1 < h and any(x != bg for x in grid[end + 1]):
        end += 1

    right = max(c for r in range(start, end + 1)
                for c in range(w) if grid[r][c] != bg)
    for r in range(start, end + 1):
        if grid[r][right] != bg:
            for c in range(right + 1, w):
                out[r][c] = 1
    return out
